// frameMonitor.ts
export interface FrameStats {
  fps: number;          // current FPS over last 1s
  frameTimeMs: number;  // last frame's ms
  p50: number;          // p50 over last 30s
  p95: number;          // p95 over last 30s
  p99: number;          // p99 over last 30s
  drawCalls: number;
  triangles: number;
  entities: number;
}

class FrameMonitor {
  private windowSize = 300; // ~5s at 60fps
  private ring: Float64Array; // frame times in ms
  private head = 0;
  private count = 0;
  private lastFpsWindowStart = 0;
  private framesInFpsWindow = 0;
  private fps = 0;
  private lastFrameMs = 0;

  // external reports
  private latestDrawCalls = 0;
  private latestTriangles = 0;
  private latestEntities = 0;

  // budgets
  private budgetWarnings = new Map<string, number>(); // name → last warn ts

  frameStarted(performanceNowMs: number): void {
    // could record start, but actual elapsed is measured at end
  }

  frameEnded(performanceNowMs: number, perfNow: () => number = () => performance.now()): void {
    // for now, accept start/end; if start was set, use elapsed
  }

  recordFrameTime(ms: number, now: number): void {
    this.ring[this.head] = ms;
    this.head = (this.head + 1) % this.windowSize;
    this.count = Math.min(this.count + 1, this.windowSize);
    this.lastFrameMs = ms;
    // update FPS
    if (this.lastFpsWindowStart === 0) this.lastFpsWindowStart = now;
    if (now - this.lastFpsWindowStart >= 1000) {
      this.fps = (this.framesInFpsWindow * 1000) / (now - this.lastFpsWindowStart);
      this.lastFpsWindowStart = now;
      this.framesInFpsWindow = 0;
    } else {
      this.framesInFpsWindow++;
    }
  }

  recordRendererInfo(drawCalls: number, triangles: number): void {...}
  recordEntityCount(n: number): void {...}

  getFrameStats(): FrameStats {...}

  budgetCheck(name: string, ms: number, now: number, warn?: (msg: string) => void): boolean {...}
}
